class Agenthub < Formula
  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.12.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.1/agenthub-0.12.1-b441b62-darwin-arm64.tar.gz"
      sha256 "97fc85c23acc3551e98e08c56637468bf48d4699ec1df1fdfcc04145bde474ac"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.1/agenthub-0.12.1-b441b62-darwin-amd64.tar.gz"
      sha256 "4c20257150692e675c6e6d5bdf4d8b54b12ec9f68001f8f1bf1375e9b1164c7e"
